const formatFlightTime = (time: string | null | undefined) => {
  if (!time) return "N/A";

  // If it's already in 12h format (contains AM/PM), just return it uppercase
  if (time.toLowerCase().includes('am') || time.toLowerCase().includes('pm')) {
    return time.toUpperCase();
  }

  try {
    // If it's just a number or something unexpected, return as is
    if (!time.includes(':')) return time.toUpperCase();

    // Assume format is HH:mm or HH:mm:ss
    const parts = time.split(':');
    const h = parseInt(parts[0], 10);
    const m = parts[1] || '00';

    if (isNaN(h)) return time.toUpperCase();

    const ampm = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 || 12;

    return `${h12}:${m.padStart(2, '0')} ${ampm}`;
  } catch (error) {
    return time.toUpperCase();
  }
};

const convertTo24Hour = (timeStr: string | null | undefined) => {
  if (!timeStr) return "";

  // If already in HH:mm format (e.g. 11:00 or 23:30)
  if (/^\d{1,2}:\d{2}(:\d{2})?$/.test(timeStr)) {
    return timeStr.split(':').slice(0, 2).join(':');
  }

  try {
    // Handle 11:00 AM or 11:00AM or 11 AM etc.
    const match = timeStr.match(/(\d{1,2})(?::(\d{2}))?\s*(AM|PM)/i);
    if (match) {
      let hours = parseInt(match[1], 10);
      const minutes = match[2] || "00";
      const ampm = match[3].toUpperCase();

      if (ampm === 'PM' && hours < 12) hours += 12;
      if (ampm === 'AM' && hours === 12) hours = 0;

      return `${hours.toString().padStart(2, '0')}:${minutes}`;
    }
  } catch (e) {
    console.warn("Error converting time:", e);
  }

  return "";
};

const extractPathFromUrl = (url: string | null | undefined) => {
  if (!url) return null;
  // Supabase URL format: https://[project-ref].supabase.co/storage/v1/object/public/[bucket]/[path]
  const bucketName = import.meta.env.VITE_SUPABASE_BUCKET || "media";
  const searchPart = `/storage/v1/object/public/${bucketName}/`;
  const index = url.indexOf(searchPart);
  if (index !== -1) {
    return url.substring(index + searchPart.length);
  }
  return null;
};

