  const routeOptions = useMemo(() => {
    const map = new Map<string, { route: string; google_maps_link: string | null }>();
    (packages || []).forEach((pkg: any) => {
      const route = String(pkg?.route || "").trim();
      if (!route) return;
      const link = pkg?.google_maps_link ? String(pkg.google_maps_link) : null;
      if (!map.has(route)) {
        map.set(route, { route, google_maps_link: link });
        return;
      }
      const existing = map.get(route)!;
      if (!existing.google_maps_link && link) existing.google_maps_link = link;
    });
    return Array.from(map.values()).sort((a, b) => a.route.localeCompare(b.route));
  }, [packages]);

