  // Helper functions (dependency order matters!)
  const isAdmin = () => {
    const profileRole = currentUserProfile?.role;
    const profileEmail = currentUserProfile?.email;
    const authEmail = session?.user?.email;

    return profileRole === 'Administrator' ||
      profileEmail === 'amirul.mustapha@yahoo.com' ||
      authEmail === 'amirul.mustapha@yahoo.com';
  };

  const canView = (tab: string) => {
    if (!currentUserProfile) return false;
    if (isAdmin()) return true;

    const userRole = currentUserProfile.role;

    // Map child modules to parent modules
    const targetModule = CHILD_TO_PARENT_MAP[tab] || tab;

    const perm = rolePermissions.find(p => p.role === userRole && p.module === targetModule);
    return perm ? perm.can_view : false;
  };

  const canNavigateTab = (tab: string) => {
    // Map child tabs to parent tabs for permission checking
    const parentTab = CHILD_TO_PARENT_MAP[tab] || tab;

    // Check permission for the parent tab
    return canView(parentTab);
  };

  const canEdit = (tab: string) => {
    if (!currentUserProfile) return false;
    if (isAdmin()) return true;

    const userRole = currentUserProfile.role;

    // Map child modules to parent modules
    const targetModule = CHILD_TO_PARENT_MAP[tab] || tab;

    const perm = rolePermissions.find(p => p.role === userRole && p.module === targetModule);
    return perm ? perm.can_edit : false;
  };

